"""Run the pinned official MASt3R Gradio demo with local files and settings."""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import sys


PROJECT_ROOT = Path(__file__).resolve().parents[1]
REPO_ROOT = PROJECT_ROOT / "repos" / "mast3r"
DEFAULT_WEIGHTS = PROJECT_ROOT / "checkpoints" / "mast3r" / "MASt3R_ViTLarge_BaseDecoder_512_catmlpdpt_metric.pth"


def configure_runtime(output_dir: Path) -> None:
    # Keep the third-party Git checkouts free of generated bytecode files.
    sys.dont_write_bytecode = True
    output_dir.mkdir(parents=True, exist_ok=True)
    temp_dir = output_dir / "gradio-temp"
    temp_dir.mkdir(exist_ok=True)
    os.environ["GRADIO_ANALYTICS_ENABLED"] = "False"
    os.environ["GRADIO_TEMP_DIR"] = str(temp_dir)
    os.environ["HF_HUB_OFFLINE"] = "1"
    os.environ["MPLBACKEND"] = "Agg"
    for name in ("NO_PROXY", "no_proxy"):
        values = [part.strip() for part in os.environ.get(name, "").split(",") if part.strip()]
        for host in ("127.0.0.1", "localhost", "::1"):
            if host not in values:
                values.append(host)
        os.environ[name] = ",".join(values)
    if not (REPO_ROOT / "mast3r" / "model.py").is_file():
        raise FileNotFoundError(f"Official MASt3R checkout is missing: {REPO_ROOT}")
    sys.path.insert(0, str(REPO_ROOT))


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--weights", type=Path, default=DEFAULT_WEIGHTS)
    parser.add_argument("--device", choices=("cuda", "cpu"), default="cuda")
    parser.add_argument("--port", "--server_port", type=int, default=7861)
    parser.add_argument("--image-size", "--image_size", type=int, choices=(224, 512), default=512)
    parser.add_argument("--output-dir", "--tmp_dir", type=Path, default=PROJECT_ROOT / "outputs" / "mast3r" / "demo")
    parser.add_argument("--check", action="store_true", help="Check imports and local files without loading the model.")
    args = parser.parse_args()
    configure_runtime(args.output_dir)

    import importlib.metadata
    import torch
    from mast3r.demo import main_demo
    from mast3r.model import AsymmetricMASt3R
    from mast3r.utils.misc import hash_md5

    if args.check:
        report = {
            "python": sys.executable,
            "base_python": sys.base_prefix,
            "repository": str(REPO_ROOT),
            "weights": str(args.weights),
            "weights_present": args.weights.is_file(),
            "cuda_available": torch.cuda.is_available(),
            "versions": {name: importlib.metadata.version(name) for name in ("torch", "torchvision", "numpy", "gradio", "trimesh", "scikit-learn")},
            "url": f"http://127.0.0.1:{args.port}",
        }
        print(json.dumps(report, ensure_ascii=False, indent=2))
        return
    if not args.weights.is_file():
        raise FileNotFoundError(f"Local checkpoint is missing: {args.weights}")
    if args.device == "cuda" and not torch.cuda.is_available():
        raise RuntimeError("CUDA is unavailable; rerun with --device cpu or check the NVIDIA/PyTorch installation.")
    torch.set_num_threads(min(8, os.cpu_count() or 1))
    torch.backends.cuda.matmul.allow_tf32 = True
    model = AsymmetricMASt3R.from_pretrained(str(args.weights)).eval().to(args.device)
    cache_dir = args.output_dir / hash_md5(str(args.weights))
    cache_dir.mkdir(exist_ok=True)
    main_demo(str(cache_dir), model, None, args.device, args.image_size,
              "127.0.0.1", args.port, silent=False, share=False, gradio_delete_cache=False)


if __name__ == "__main__":
    main()
